	@Test
	void jsonpPreservesCallbackAfterLeadingHeartbeatWhitespace() throws Exception {
		TupleQueryResultWriterFactory factory = TupleQueryResultWriterRegistry.getInstance()
				.get(TupleQueryResultFormat.JSON)
				.orElseThrow();
		RecordingOutputStream target = new RecordingOutputStream();
		QueryResponseHeartbeat heartbeat = newHeartbeat(target);
		try {
			TupleQueryResultWriter writer = factory.getWriter(heartbeat.getOutputStream());
			writer.getWriterConfig().set(BasicQueryWriterSettings.JSONP_CALLBACK, "heartbeatCallback");
			assertThat(heartbeat.start(writer)).isTrue();
			awaitProbes(target);

			writer.startQueryResult(BINDING_NAMES);
			writer.handleSolution(BINDING_SET);
			writer.endQueryResult();
			heartbeat.complete();

			String serialized = target.toString(StandardCharsets.UTF_8);
			assertThat(serialized).matches("(?s)^\\s+heartbeatCallback\\(.*\\);$");
		} finally {
			heartbeat.close();
		}
	}

