	private static void assertTupleRoundTrip(TupleQueryResultWriterFactory factory, List<BindingSet> rows)
			throws Exception {
		TupleQueryResultFormat format = factory.getTupleQueryResultFormat();
		RecordingOutputStream target = new RecordingOutputStream();
		QueryResponseHeartbeat heartbeat = newHeartbeat(target);
		byte[] serialized;
		try {
			TupleQueryResultWriter writer = factory.getWriter(heartbeat.getOutputStream());
			assertThat(heartbeat.start(writer)).as(format.getName()).isTrue();
			awaitProbes(target);

			writer.startQueryResult(BINDING_NAMES);
			for (BindingSet row : rows) {
				writer.handleSolution(row);
			}
			writer.endQueryResult();
			heartbeat.complete();
			assertThat(target.flushCount.get()).as(format.getName()).isGreaterThanOrEqualTo(2);
			serialized = target.toByteArray();
		} finally {
			heartbeat.close();
		}

		assertXmlHasNoDeclaration(format, serialized);
		TupleQueryResultBuilder builder = new TupleQueryResultBuilder();
		TupleQueryResultParser parser = QueryResultIO.createTupleParser(format);
		parser.setTupleQueryResultHandler(builder);
		parser.parseQueryResult(new ByteArrayInputStream(serialized));
		TupleQueryResult parsed = builder.getQueryResult();
		try {
			int count = 0;
			while (parsed.hasNext()) {
				BindingSet row = parsed.next();
				assertThat(row.getValue("value")).isEqualTo(BINDING_SET.getValue("value"));
				count++;
			}
			assertThat(count).as(format.getName()).isEqualTo(rows.size());
		} finally {
			parsed.close();
		}
	}

