	private static void assertRdfRoundTrip(RDFWriterFactory factory, List<Statement> statements) throws Exception {
		RDFFormat format = factory.getRDFFormat();
		RecordingOutputStream target = new RecordingOutputStream();
		QueryResponseHeartbeat heartbeat = newHeartbeat(target);
		byte[] serialized;
		try {
			RDFWriter writer = factory.getWriter(heartbeat.getOutputStream());
			assertThat(heartbeat.start(writer)).as(format.getName()).isTrue();
			awaitProbes(target);

			writer.startRDF();
			if (RDFFormat.JSONLD.equals(format) || RDFFormat.RDFJSON.equals(format)) {
				assertThat(heartbeat.hasPayload()).as(format.getName()).isFalse();
				assertOnlyProbeWhitespace(target, format);
			}
			for (Statement statement : statements) {
				writer.handleStatement(statement);
			}
			writer.endRDF();
			heartbeat.complete();
			assertThat(target.flushCount.get()).as(format.getName()).isGreaterThanOrEqualTo(2);
			serialized = target.toByteArray();
		} finally {
			heartbeat.close();
		}

		assertXmlHasNoDeclaration(format, serialized);
		Model parsed = Rio.parse(new ByteArrayInputStream(serialized), "urn:heartbeat:base:", format);
		assertThat(parsed).as(format.getName()).containsExactlyInAnyOrderElementsOf(statements);
	}

