	private static void assertXmlHasNoDeclaration(Object format, byte[] serialized) {
		if (TupleQueryResultFormat.SPARQL.equals(format)
				|| org.eclipse.rdf4j.query.resultio.BooleanQueryResultFormat.SPARQL.equals(format)
				|| RDFFormat.RDFXML.equals(format)
				|| RDFFormat.TRIX.equals(format)) {
			String text = new String(serialized, StandardCharsets.UTF_8);
			assertThat(text).doesNotContain("<?xml");
			assertThat(text.stripLeading()).startsWith("<");
		}
	}

